		#region Create Job Headers

		internal void CreateJobHeader()
		{
			BusinessObject[] selectedShipments = InnerGrid.SelectedElements;
			if (selectedShipments.Length == 0)
			{
				Globals.Message.Show(Res.GetString("530ef6df-46a1-48a3-9fef-59847bd1dc93", "Please select shipments to create Job Invoicing Record."),
					Res.GetString("2b789fb1-a06b-4e5e-957a-be153a8b5596", "Select Shipment"), MessageBoxButtons.OK, MessageBoxIcon.Warning);
			}
			else
			{
				var shipmentsWithoutHeaders = selectedShipments.Cast<CommonShipment>().Where(x => x.ShipmentJobHeader == null).ToArray();
				var shipmentsWithUnsavedHeaders = selectedShipments.Cast<CommonShipment>().Where(x => x.ShipmentJobHeader != null && !x.ShipmentJobHeader.IsInDatabase && !x.ShipmentJobHeader.IsManuallyCreated).ToArray();
				if (shipmentsWithoutHeaders.Length == 0 && shipmentsWithUnsavedHeaders.Length == 0)
				{
					Globals.Message.Show(Res.GetString("f3b7a641-5bfa-43b4-bb77-27a8da37aa33", "These shipments already have Job Invoicing Record created."), Res.GetString("2de57dcc-d627-4baf-a418-8f01393f2dc7", "Create Job Invoicing Record"), MessageBoxButtons.OK, MessageBoxIcon.Information);
				}
				else
				{
					var shipmentsToIterate = shipmentsWithoutHeaders.Union(shipmentsWithUnsavedHeaders);

					var shipmentsWithCreatedHeaders = new ZStringBuilder();
					var jobCreationErrors = new ZStringBuilder();
					var shipmentsWithUnsavedHeaderMarkedManuallyCreated = new ZStringBuilder();

					foreach (CommonShipment shipment in shipmentsToIterate)
					{
						if (!shipment.ReadOnly && !shipment.IsReadOnlyDueToPhase)
						{
							if (shipment.ShipmentJobHeader == null)
							{
								var errorMessaage = shipment.CreateShipmentJobHeaderWithMutex();
								if (!string.IsNullOrEmpty(errorMessaage))
								{
									jobCreationErrors.AppendIfNotEmpty(errorMessaage);
								}
								else
								{
									shipment.HasChanges = true;
									shipmentsWithCreatedHeaders.Append("- " + shipment.HumanReadableName);
								}
							}
							else
							{
								shipment.ShipmentJobHeader.IsManuallyCreated = true;
								shipment.HasChanges = true;
								shipmentsWithUnsavedHeaderMarkedManuallyCreated.Append("- " + shipment.HumanReadableName);
							}
						}
						else
						{
							jobCreationErrors.Append(Res.GetString("e1cff15b-001a-455e-ba17-f597ee421c75", "{0} is read only", shipment.HumanReadableName));
						}
					}

					ZStringBuilder questionMessage = new ZStringBuilder();
					if (shipmentsWithCreatedHeaders.Length > 0)
					{
						questionMessage.AppendLine(Res.GetString("cdc8908a-ce4b-45d2-93da-18a98971daf3", "Job Invoicing Record has been created for the following shipment(s):\r\n{0}", shipmentsWithCreatedHeaders.ToStringWithNewLineBetweenAppends()));
					}

					if (shipmentsWithUnsavedHeaderMarkedManuallyCreated.Length > 0)
					{
						if (questionMessage.Length > 0)
						{
							questionMessage.Append(System.Environment.NewLine);
						}
						questionMessage.AppendLine(Res.GetString("bb4a8eb4-dba9-4b86-b6f2-f2e7e48df17f", "Existing unsaved Job Invoicing Record has been marked as manually created for the following shipment(s):\r\n{0}", shipmentsWithUnsavedHeaderMarkedManuallyCreated.ToStringWithNewLineBetweenAppends()));
					}

					if (jobCreationErrors.Length > 0)
					{
						if (questionMessage.Length > 0)
						{
							questionMessage.Append(System.Environment.NewLine);
						}
						questionMessage.AppendLine(Res.GetString("f2fdf563-cb56-40fe-9caf-8996902b263f", "For other shipment(s) it can't be done due to the following errors:\r\n{0}", jobCreationErrors.ToStringWithNewLineBetweenAppends()));
					}

					Globals.Message.Show(questionMessage.ToString(), Res.GetString("2de57dcc-d627-4baf-a418-8f01393f2dc7", "Create Job Invoicing Record"), MessageBoxButtons.OK, MessageBoxIcon.Information);
				}
			}
		}

